+		t, err := time.Parse(time.RFC3339, v)
+		if err != nil {
+			return time.Time{}, time.Time{}, errors.New("end must be RFC3339, e.g. 2026-09-22T01:00:00Z")
+		}
+		to = t
+	}
+	if from.After(to) {
