+func New(addr string, echoCache *cache.EchoCache, store *storage.Postgres,
+	ingest IngestStats, logger *slog.Logger) *Server {
+	gin.SetMode(gin.ReleaseMode)
+	r := gin.New()
+	r.Use(gin.Recovery())
+	r.Use(requestLogger(logger))
